"""Tiny Color·Gray wafer on disk for tests (real JPEGs made once with Chromium's canvas —
the project has no Pillow)."""
import base64
from pathlib import Path

COLOR_JPEG = base64.b64decode("")
GRAY_JPEG = base64.b64decode("")


def make_wafer(folder, name="W01"):
    """One wafer: 3 color images — C1 matches two frames (F1 wins, farther from the edge),
    C2 matches none, C3 names a missing color file."""
    w = Path(folder) / name
    w.mkdir(parents=True, exist_ok=True)
    (w / "C1.jpg").write_bytes(COLOR_JPEG)
    (w / "F1.t.1.jpg").write_bytes(GRAY_JPEG)
    (w / "F2.t.1.jpg").write_bytes(GRAY_JPEG)
    (w / "ColorImageGrabingInfo.ini").write_text(
        "[C1.jpg]\nFaultX=1100\nFaultY=200\nRecipeNumber=1\nImageSizeX=46\nImageSizeY=34\n"
        "PixelSizeX=0.4674\nPixelSizeY=0.4674\n"
        "[C2.jpg]\nFaultX=90000\nFaultY=90000\nRecipeNumber=1\n"
        "[C3.jpg]\nFaultX=1100\nFaultY=210\nRecipeNumber=1\n", encoding="utf-8")
    (w / "ScanResultImageList.txt").write_text("Version=1\nF1.t.1.jpg,0,0\nF2.t.1.jpg,1000,0\n", encoding="utf-8")
    (w / "frameToChuckPlane.1.ini").write_text("Scan_X=1 0 0\nScan_Y=0 1 0\n", encoding="utf-8")
    return w
